package com.bank.report;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Produces a rank-by-rank (level order) view of the hierarchy.
public class HierarchyLevelService {

    private static final Logger log = Logger.getLogger(HierarchyLevelService.class.getName());

    public List<List<String>> levelOrder(ApproverNode root) {
        List<List<String>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }
        Queue<ApproverNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();        // snapshot this level's width
            List<String> level = new ArrayList<>(levelSize);
            for (int i = 0; i < levelSize; i++) {
                ApproverNode node = queue.poll();
                level.add(node.getRole());
                if (node.getLeft() != null) queue.offer(node.getLeft());
                if (node.getRight() != null) queue.offer(node.getRight());
            }
            result.add(level);
        }
        return result;
    }

    public void reportByRank(ApproverNode root) {
        List<List<String>> levels = levelOrder(root);
        for (int i = 0; i < levels.size(); i++) {
            int rank = i;
            log.info(() -> "Rank " + rank + ": " + levels.get(rank));
        }
    }
}
