package com.bank.report;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LevelOrderDemo {

    private static final Logger log = Logger.getLogger(LevelOrderDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Approval Hierarchy by Rank");

        //            Manager
        //          /         \
        //    CreditOfficer   RiskHead
        //      /      \          \
        //  JrA       JrB      RegionalVP
        ApproverNode manager = new ApproverNode("Manager");
        ApproverNode credit = new ApproverNode("CreditOfficer");
        ApproverNode risk = new ApproverNode("RiskHead");
        manager.setLeft(credit);
        manager.setRight(risk);
        credit.setLeft(new ApproverNode("JrA"));
        credit.setRight(new ApproverNode("JrB"));
        risk.setRight(new ApproverNode("RegionalVP"));

        new HierarchyLevelService().reportByRank(manager);
    }
}
